// Copies the protocol bindings generated by the Rust `runtimes` crate into src/generated/.
// The copies are committed so the sidecar builds without a Rust toolchain.
import { copyFileSync, mkdirSync, readdirSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const from = join(here, '..', '..', '..', 'crates', 'runtimes', 'bindings');
const to = join(here, '..', 'src', 'generated');

rmSync(to, { recursive: true, force: true });
mkdirSync(to, { recursive: true });
const files = readdirSync(from).filter((f) => f.endsWith('.ts'));
for (const f of files) copyFileSync(join(from, f), join(to, f));
console.log(`copied ${files.length} binding files`);
